  const out = []
  for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
    for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) out.push(cellValue(keyOf(c, r)))
