    case 'ref': {
      const a = parseAddr(n.w)
      return a ? cellValue(a.key) : err('#REF!')
    }
    case 'un': {
      const v = ev(n.e)
      if (v.k === 'e') return v
      const x = toNum(v)
      if (x.k === 'e') return x
      return n.op === '-' ? num(-x.v) : x
    }
    case 'bin': {
      const l = ev(n.l), r = ev(n.r)
      if (l.k === 'e') return l
      if (r.k === 'e') return r
      if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
        const d = compare(l, r)
        const res = { '=': d === 0, '<>': d !== 0, '<': d < 0, '<=': d <= 0, '>': d > 0, '>=': d >= 0 }[n.op]
        return { k: 'b', v: res }
