  const vals = []
  for (const a of args) {
    if (a.type === 'range') vals.push(...rangeValues(a.a, a.b))
    else vals.push(ev(a))
  }
  const e = vals.find((v) => v.k === 'e')
  if (e) return e
  if (name === 'COUNT') return num(vals.filter((v) => v.k === 'n').length)
  const nums = []
  for (const v of vals) {
    const x = toNum(v)
    if (x.k === 'e') return x
    nums.push(x.v)
  }
  if (name === 'SUM') return fin(nums.reduce((s, x) => s + x, 0))
  if (name === 'MIN') return num(Math.min(...nums))
  if (name === 'MAX') return num(Math.max(...nums))
  return fin(nums.reduce((s, x) => s + x, 0) / nums.length)
