  for (const c of sorted) {
    const set = new Map()
    if (c.formula && c.ast) collect(c.ast, set)
    const l = [...set.values()].sort((x, y) => x.col - y.col || x.row - y.row)
    out.push(`${c.a.key}:` + l.map((a) => ' ' + a.key).join(''))
  }
}
function collect(n, set) {
  if (n.type === 'ref') {
    const a = parseAddr(n.w)
    if (a) set.set(a.key, a)
  } else if (n.type === 'range') {
    const x = parseAddr(n.a), y = parseAddr(n.b)
    if (x && y)
      for (let c = Math.min(x.col, y.col); c <= Math.max(x.col, y.col); c++)
        for (let r = Math.min(x.row, y.row); r <= Math.max(x.row, y.row); r++) set.set(keyOf(c, r), { col: c, row: r, key: keyOf(c, r) })
  } else if (n.type === 'un') collect(n.e, set)
  else if (n.type === 'bin') { collect(n.l, set); collect(n.r, set) }
  else if (n.type === 'call') n.args.forEach((a) => collect(a, set))
}
